Fixes: 63f13937cbe9 ("net: linkwatch: add net device refcount tracker")
Signed-off-by: Eric Dumazet <edumazet@google.com>
Reported-by: syzbot <syzkaller@googlegroups.com>
Link: https://lore.kernel.org/r/20211214051955.3569843-1-eric.dumazet@gmail.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The bug is caused by a race condition where `linkwatch_add_event()` can be executed concurrently while `__linkwatch_run_queue()` is processing, leading to the potential premature release of `dev->linkwatch_dev_tracker`. This can result in a use-after-free scenario, where the tracker is accessed after it has been freed, causing undefined behavior and crashes.

Here is the patch:

 static void linkwatch_do_dev(struct net_device *dev)
 {
 	/*
 	 * Make sure the above read is complete since it can be
 	 * rewritten as soon as we clear the bit below.
 	 */
 	smp_mb__before_atomic();

 	/* We are about to handle this device,
 	 * so new events can be accepted
 	 */
 	clear_bit(__LINK_STATE_LINKWATCH_PENDING, &dev->state);

 	rfc2863_policy(dev);
 	if (dev->flags & IFF_UP) {
 		if (netif_carrier_ok(dev))
 			dev_activate(dev);
 		else
 			dev_deactivate(dev);

 		netdev_state_change(dev);
 	}
-	dev_put_track(dev, &dev->linkwatch_dev_tracker);
+	/* Note: our callers are responsible for
+	 * calling netdev_tracker_free().
+	 */
+	dev_put(dev);
 }

 static void __linkwatch_run_queue(int urgent_only)
 {
 #define MAX_DO_DEV_PER_LOOP	100

 	int do_dev = MAX_DO_DEV_PER_LOOP;
 	struct net_device *dev;
 	LIST_HEAD(wrk);

 	/* Give urgent case more budget */
 	if (urgent_only)
 		do_dev += MAX_DO_DEV_PER_LOOP;

 	/*
 	 * Limit the number of linkwatch events to one
 	 * per second so that a runaway driver does not
 	 * cause a storm of messages on the netlink
 	 * socket.  This limit does not apply to up events
 	 * while the device qdisc is down.
 	 */
 	if (!urgent_only)
 		linkwatch_nextevent = jiffies + HZ;
 	/* Limit wrap-around effect on delay. */
 	else if (time_after(linkwatch_nextevent, jiffies + HZ))
 		linkwatch_nextevent = jiffies;

 	clear_bit(LW_URGENT, &linkwatch_flags);

 	spin_lock_irq(&lweventlist_lock);
 	list_splice_init(&lweventlist, &wrk);

 	while (!list_empty(&wrk) && do_dev > 0) {

 		dev = list_first_entry(&wrk, struct net_device, link_watch_list);
 		list_del_init(&dev->link_watch_list);

 		if (!netif_device_present(dev) ||
 		    (urgent_only && !linkwatch_urgent_event(dev))) {
 			list_add_tail(&dev->link_watch_list, &lweventlist);
 			continue;
 		}
+		/* We must free netdev tracker under
+		 * the spinlock protection.
+		 */
+		netdev_tracker_free(dev, &dev->linkwatch_dev_tracker);
 		spin_unlock_irq(&lweventlist_lock);
 		linkwatch_do_dev(dev);
 		do_dev--;
 		spin_lock_irq(&lweventlist_lock);
 	}

 	/* Add the remaining work back to lweventlist */
 	list_splice_init(&wrk, &lweventlist);

 	if (!list_empty(&lweventlist))
 		linkwatch_schedule_work(0);
 	spin_unlock_irq(&lweventlist_lock);
 }

 void linkwatch_forget_dev(struct net_device *dev)
 {
 	unsigned long flags;
 	int clean = 0;

 	spin_lock_irqsave(&lweventlist_lock, flags);
 	if (!list_empty(&dev->link_watch_list)) {
 		list_del_init(&dev->link_watch_list);
 		clean = 1;
+		/* We must release netdev tracker under
+		 * the spinlock protection.
+		 */
+		netdev_tracker_free(dev, &dev->linkwatch_dev_tracker);
 	}
 	spin_unlock_irqrestore(&lweventlist_lock, flags);
 	if (clean)
 		linkwatch_do_dev(dev);
 }



